// === Tab: mySketch ===
let exportRatio = 300 / 72;//計算輸出比例>>我之後要縮放幾倍
let Canvas;
// 定義我的畫布尺寸
let myPaper = {
  width: 3508,
  height: 2480
}

var particles;
var img = [];
var n, s, maxR;
var indexImg = 0;

function setup() {

  // 設定畫布大小，根據 exportRatio 計算
  let w = myPaper.width / exportRatio;
  let h = myPaper.height / exportRatio;
  canvas = createCanvas(w, h);

  background(0);
  smooth();

  // 根據螢幕像素密度調整 exportRatio
  exportRatio /= pixelDensity();

  // 設定初始粒子參數
  n = 6000;
  s = 10;
  maxR = height / 2 - height / 10;
  particles = [];

  // 置入圖片
  MyImage();
}

function draw() {
  // 設置畫布背景及旋轉效果
	// background(0,100);
  translate(width / 2, height / 2);
	// rotate(frameCount/1000+sin(frameCount%100))//Version2
  rotate(frameCount / 1000);//Version3
  noStroke();
	// addNoise()
  blendMode(LIGHTEST);

  // 繪製粒子效果
  calculateWork();
}

// 儲存高品質圖片
function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop(); // 停止繪畫循環

   // 重新縮放與重繪
    push();
    scale(exportRatio);
    pop();

    // 儲存為 PNG 格式
    saveCanvas("Mywork", 'png');

  }
}


// === Tab: graphic ===
function calculateWork() {
	if(s > 1) {
		if(particles.length != 0) {
			for(let i = 0; i < particles.length; i++) {
				var p = particles[i];
				p.show();
				p.move();

				if(p.isDead()) particles.splice(i, 1);
			}
		} else {
			s -= 2;
			initParticles();
		}
	}


}

function initParticles() {	
	for(let i = 0; i < n; i++) {
		particles.push(new Particle(maxR, s));

		var p = particles[i];
		var x = int(map(p.pos.x, -maxR, maxR, 0, img[indexImg].width));
    var y = int(map(p.pos.y, -maxR, maxR, 0, img[indexImg].height));
		p.c = img[indexImg].get(x, y);
	}
}

// function mousePressed() {
// 	indexImg = (indexImg + 1) % img.length;
// 	setup();
// }

class Particle {

  constructor(maxR_, s_) {
    this.s = s_;
    this.c = "";
    this.maxR = maxR_;

    // this.life = 100;
		this.life = 5000;

    this.init();
  }

  init() {
    this.pos = p5.Vector.random2D();
    this.pos.normalize();
    this.pos.mult(random(2, maxR));

    this.vel = createVector();
  }

  show() {
    fill(this.c);
    ellipse(this.pos.x, this.pos.y, random(this.s/8),random(this.s/8));
		 // rect(this.pos.x, this.pos.y, this.s, this.s);
    this.life -= 1;
  }

  move() {
    // var angle = noise(this.pos.x / 400, this.pos.y / 400) * TAU;
		var angle = noise(this.pos.x /100, this.pos.y / 100) * TAU;
    var fc = frameCount/int(random(10,1000))

    this.vel.set(cos(angle)/fc*20, sin(angle)/fc*0.8);//Universe
		 // this.vel.set(cos(angle)/fc*20, sin(angle)/fc*60);
    this.vel.mult(0.25);
    this.pos.add(this.vel);
  }


  isDead() {
    var d = dist(random(this.pos.x), random(this.pos.y), random(100,800), random(100,800));

    if(d > this.maxR+1000 || this.life < 1) return true;
    else return false;
  }
}

